"use client";

import Link from "next/link";
import { useParams, useSearchParams } from "next/navigation";

export default function SectionPage() {
  const params = useParams();
  const searchParams = useSearchParams();

  const idParam = params?.id;
  const sectionParam = params?.section;

  const id = Array.isArray(idParam)
    ? idParam[0]
    : String(idParam ?? "");

  const section = Array.isArray(sectionParam)
    ? sectionParam[0]
    : String(sectionParam ?? "");

  const lang = searchParams.get("lang") || "RU";

  return (
    <main
      style={{
        minHeight: "100vh",
        padding: "40px",
        background: "#eef5fa",
      }}
    >
      <div
        style={{
          maxWidth: "900px",
          margin: "0 auto",
          padding: "40px",
          background: "white",
          borderRadius: "16px",
        }}
      >
        <Link
          href={`/modules/${id}?lang=${lang}`}
          style={{
            color: "#004b87",
            fontWeight: "bold",
          }}
        >
          ← Назад к модулю
        </Link>

        <h1 style={{ color: "#004b87" }}>
          Модуль {id}
        </h1>

        <h2>
          Раздел: {section}
        </h2>

        <p>Язык: {lang}</p>

        <p>Страница раздела работает ✓</p>

        <hr style={{ margin: "30px 0" }} />

        <p>
          Адрес возврата:
          {" "}
          <strong>
            /modules/{id}?lang={lang}
          </strong>
        </p>
      </div>
    </main>
  );
}